package epicsquid.roots.container;

import epicsquid.roots.handler.ClientPouchHandler;
import epicsquid.roots.handler.IPouchHandler;
import epicsquid.roots.handler.PouchHandler;
import epicsquid.roots.init.HerbRegistry;
import epicsquid.roots.item.ItemPouch;
import epicsquid.roots.item.PouchType;
import epicsquid.roots.util.CommonHerbUtil;
import epicsquid.roots.util.ServerHerbUtil;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.InventoryPlayer;
import net.minecraft.inventory.ClickType;
import net.minecraft.inventory.Container;
import net.minecraft.inventory.Slot;
import net.minecraft.item.ItemStack;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.IItemHandlerModifiable;
import net.minecraftforge.items.SlotItemHandler;

import javax.annotation.Nonnull;
import java.util.Objects;

public class ContainerPouch extends Container {

	private IItemHandlerModifiable inventoryHandler;
	private IItemHandlerModifiable herbsHandler;
	private IPouchHandler handler;
	private EntityPlayer player;
	private ItemStack pouch;

	private int inventoryBegin;
	private int herbsBegin;
	private int inventoryEnd;
	private int herbsEnd;

	private boolean isServerSide;

	public ContainerPouch(EntityPlayer player, boolean isServerSide) {
		this.player = player;
		this.isServerSide = isServerSide;
		ItemStack main = player.getHeldItemMainhand();
		ItemStack off = player.getHeldItemOffhand();
		ItemStack first;
		if (isServerSide) {
			first = ServerHerbUtil.getFirstPouch(player);
		} else {
			first = CommonHerbUtil.getFirstPouch(player);
		}

		ItemStack use = ItemStack.EMPTY;
		if (main.getItem() instanceof ItemPouch) {
			use = main;
		} else if (off.getItem() instanceof ItemPouch) {
			use = off;
		} else if (first.getItem() instanceof ItemPouch) {
			use = first;
		}

		if (isServerSide) {
			handler = PouchHandler.getHandler(use);
		} else {
			handler = new ClientPouchHandler(use);
		}
		inventoryHandler = handler.getInventory();
		herbsHandler = handler.getHerbs();

		pouch = use;

		createPlayerInventory(player.inventory);
		createPouchSlots();
	}

	private void createPouchSlots() {
		if (isApothecary()) {
			createApothecaryPouchSlots();
		} else if (isFey()) {
			createFeyPouchSlots();
		} else if (isHerb()) {
			createHerbPouchSlots();
		} else {
			createComponentPouchSlots();
		}
	}

	public boolean isApothecary() {
		return handler.isApothecary();
	}

	public boolean isHerb() {
		return handler.isHerb();
	}

	public boolean isFey() {
		return handler.isFey();
	}

	private void createHerbPouchSlots() {
		int xOffset = -80;
		int yOffset = -50;
		for (int i = 0; i < PouchType.HERB_POUCH_SLOTS; i++) {
			// Controls which row the slots appear on
			int yPosOffset = 0;
			if (i >= 3) {
				yPosOffset += 21;
			}
			if (i >= 6) {
				yPosOffset += 22;
			}
			addSlotToContainer(new PouchSlot(herbsHandler, true, i, xOffset + 127 + (21 * (i % 3)), yOffset + 23 + yPosOffset));
		}
		herbsBegin = 0;
		herbsEnd = 9;
		inventoryBegin = 0;
		inventoryEnd = 0;
	}

	private void createFeyPouchSlots() {
		int xOffset = 13;
		int yOffset = -44;
		int q = 0;
		herbsBegin = q;
		for (int i = 0; i < 3; i++) {
			for (int j = 0; j < 4; j++) {
				addSlotToContainer(new PouchSlot(herbsHandler, j + i * 4, xOffset + j * 20, 22 + yOffset + i * 20));
				q++;
			}
		}
		herbsEnd = q;
		inventoryBegin = q;
		// 1st: 103, -21, 123, -21
		//  2nd: 103, -1, 123, -1
		// 3rd: 103, 19, 123, 19
		addSlotToContainer(new PouchSlot(inventoryHandler, 0, 103, -21));
		addSlotToContainer(new PouchSlot(inventoryHandler, 1, 123, -21));
		addSlotToContainer(new PouchSlot(inventoryHandler, 2, 103, -1));
		addSlotToContainer(new PouchSlot(inventoryHandler, 3, 123, -1));
		addSlotToContainer(new PouchSlot(inventoryHandler, 4, 103, 19));
		addSlotToContainer(new PouchSlot(inventoryHandler, 5, 123, 19));
		inventoryEnd = q + 6;
	}

	private void createComponentPouchSlots() {
		int xOffset = -13;
		int yOffset = -55;
		int q = 0;
		inventoryBegin = q;
		for (int i = 0; i < PouchType.COMPONENT_POUCH_INVENTORY_SLOTS; i++) {
			// Top Row
			if (i < 5) {
				addSlotToContainer(new PouchSlot(inventoryHandler, q++, xOffset + 11 + (i * 21), yOffset + 23));
			}
			// Middle Row
			if (i >= 5 && i < 9) {
				addSlotToContainer(new PouchSlot(inventoryHandler, q++, xOffset + 22 + ((i - 5) * 21), yOffset + 44));
			}
			// Bottom Row
			if (i >= 9 && i < 12) {
				addSlotToContainer(new PouchSlot(inventoryHandler, q++, xOffset + 33 + ((i - 9) * 21), yOffset + 65));
			}
			// Herb Pouch
		}
		inventoryEnd = q;
		herbsBegin = q;
		for (int i = 0; i < PouchType.COMPONENT_POUCH_HERB_SLOTS; i++) {
			if (q >= 12 && q < 18) {
				// Controls which row the slots appear on
				int yPosOffset = q >= 14 ? q >= 16 ? 21 * 2 : 21 : 0;
				addSlotToContainer(new PouchSlot(herbsHandler, true, i, xOffset + 127 + (21 * (q % 2)), yOffset + 23 + yPosOffset));
				q++;
			}
		}
		herbsEnd = q;
	}

	private void createApothecaryPouchSlots() {
		int xOffset = -35;
		int yOffset = -63;
		int q = 0;
		inventoryBegin = q;
		for (int i = 0; i < PouchType.APOTHECARY_POUCH_INVENTORY_SLOTS; i++) {
			// Top Row
			if (i < 6) {
				addSlotToContainer(new PouchSlot(inventoryHandler, q, xOffset + 25 + (20 * (q % 6)), yOffset + 19));
			}
			// Middle Slot
			if (i >= 6 && i < 12) {
				addSlotToContainer(new PouchSlot(inventoryHandler, q, xOffset + 25 + (20 * (q % 6)), yOffset + 43));
			}
			// Bottom Slot
			if (i >= 12 && i < 18) {
				addSlotToContainer(new PouchSlot(inventoryHandler, q, xOffset + 25 + (20 * (q % 6)), yOffset + 66));
			}
			q++;
		}
		inventoryEnd = q;
		herbsBegin = q;
		for (int i = 0; i < PouchType.APOTHECARY_POUCH_HERB_SLOTS; i++) {
			// Add Herb Slots
			q = inventoryEnd + i;
			if (q >= 18 && q < 21) {
				addSlotToContainer(new PouchSlot(herbsHandler, true, i, xOffset + 149 + (16 * (q % 3)), yOffset + 16 + (4 * (q % 2))));
			}
			if (q >= 21 && q < 24) {
				addSlotToContainer(new PouchSlot(herbsHandler, true, i, xOffset + 149 + (16 * (q % 3)), yOffset + 39 + (4 * ((q + 1) % 2))));
			}
			if (q >= 24 && q < 27) {
				addSlotToContainer(new PouchSlot(herbsHandler, true, i, xOffset + 149 + (16 * (q % 3)), yOffset + 64 + (4 * (q % 2))));
			}
		}
		herbsEnd = q;
	}

	private void createPlayerInventory(InventoryPlayer inventoryPlayer) {

		int xOffset = -5;
		int yOffset = 70;

		for (int i = 0; i < 3; i++) {
			for (int j = 0; j < 9; j++) {
				addSlotToContainer(new Slot(inventoryPlayer, j + i * 9 + 9, xOffset + j * 18, yOffset + i * 18));
			}
		}
		for (int i = 0; i < 9; i++) {
			addSlotToContainer(new Slot(inventoryPlayer, i, xOffset + i * 18, yOffset + 58));
		}
	}

	@Override
	public boolean canInteractWith(@Nonnull EntityPlayer player) {
		ItemStack main = player.getHeldItemMainhand();
		ItemStack off = player.getHeldItemOffhand();
		ItemStack first = ServerHerbUtil.getFirstPouch(player);
		return (main.equals(pouch) || off.equals(pouch) || first.equals(pouch));
	}

	@Override
	@Nonnull
	public ItemStack transferStackInSlot(EntityPlayer playerIn, int index) {
		ItemStack slotStack = ItemStack.EMPTY;

		Slot slot = inventorySlots.get(index);
		int herbStart = herbsBegin + 36;
		int herbStop = herbsEnd + 36;
		int inventoryStart = inventoryBegin + 36;
		int inventoryStop = inventoryEnd + 36;

		if (slot != null && slot.getHasStack()) {
			ItemStack stack = slot.getStack();
			slotStack = stack.copy();

			boolean herb = HerbRegistry.isHerb(slotStack.getItem());

			if (index < 36) { // Player Inventory -> Inventory/herbs
				if (herb && !mergeItemStack(stack, herbStart, herbStop, false)) {
					if (!mergeItemStack(stack, inventoryStart, inventoryStop, false)) {
						return ItemStack.EMPTY;
					}
				} else if (!herb && !mergeItemStack(stack, inventoryStart, inventoryStop, false)) {
					return ItemStack.EMPTY;
				}
			} else {
				if (!mergeItemStack(stack, 27, 36, false) && !mergeItemStack(stack, 0, 27, false)) {
					return ItemStack.EMPTY;
				}
			}

			if (stack.isEmpty()) {
				slot.putStack(ItemStack.EMPTY);
			}

			slot.onSlotChanged();
		}

		return slotStack;
	}

	@Override
	@Nonnull
	public ItemStack slotClick(int slotId, int dragType, ClickType clickTypeIn, EntityPlayer player) {
		if (slotId >= 0) {
			ItemStack stack = getSlot(slotId).getStack();
			if (stack.getItem() instanceof ItemPouch) {
				return ItemStack.EMPTY;
			}
		}

		return super.slotClick(slotId, dragType, clickTypeIn, player);
	}

	@Override
	public void detectAndSendChanges() {
		super.detectAndSendChanges();

		handler.markDirty();
	}

	@Override
	public void onContainerClosed(EntityPlayer playerIn) {
		super.onContainerClosed(playerIn);

		if (!player.world.isRemote) {
			Objects.requireNonNull(player.world.getMapStorage()).saveAllData();
		}
	}

	public class PouchSlot extends SlotItemHandler {
		private final boolean herb;

		public PouchSlot(IItemHandler itemHandler, boolean herb, int index, int xPosition, int yPosition) {
			super(itemHandler, index, xPosition, yPosition);
			this.herb = herb;
		}

		public PouchSlot(IItemHandler itemHandler, int index, int xPosition, int yPosition) {
			super(itemHandler, index, xPosition, yPosition);
			this.herb = false;
		}

		@Override
		public boolean isItemValid(@Nonnull ItemStack stack) {
			if (stack.getItem() instanceof ItemPouch) {
				return false;
			}

			if (herb && !HerbRegistry.isHerb(stack.getItem())) {
				return false;
			}

			return super.isItemValid(stack);
		}

		@Override
		public void onSlotChange(@Nonnull ItemStack stack1, @Nonnull ItemStack stack2) {
			super.onSlotChange(stack1, stack2);
			handler.markDirty();
		}

		@Override
		public void onSlotChanged() {
			super.onSlotChanged();
			handler.markDirty();
		}
	}
}

package epicsquid.roots.event;

import epicsquid.mysticallib.block.BlockBase;
import epicsquid.roots.Roots;
import epicsquid.roots.config.GeneralConfig;
import epicsquid.roots.entity.item.EntityItemMagmaticSoil;
import epicsquid.roots.handler.PouchHandler;
import epicsquid.roots.init.HerbRegistry;
import epicsquid.roots.init.ModBlocks;
import epicsquid.roots.init.ModItems;
import epicsquid.roots.item.ItemRunicShears;
import epicsquid.roots.util.ServerHerbUtil;
import net.minecraft.entity.Entity;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.init.SoundEvents;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.util.EnumActionResult;
import net.minecraft.util.EnumHand;
import net.minecraft.util.SoundCategory;
import net.minecraft.util.math.Vec3d;
import net.minecraftforge.event.entity.EntityJoinWorldEvent;
import net.minecraftforge.event.entity.player.EntityItemPickupEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.eventhandler.EventPriority;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;

import java.util.List;

@Mod.EventBusSubscriber(modid = Roots.MODID)
@SuppressWarnings("unused")
public class ItemEventHandler {

	@SubscribeEvent(priority = EventPriority.HIGHEST)
	public static void onInteract(PlayerInteractEvent.RightClickBlock event) {
		if (event.getHand() != EnumHand.MAIN_HAND)
			return;

		EntityPlayer player = event.getEntityPlayer();
		ItemStack main = player.getHeldItemMainhand();
		if (main.getItem() != ModItems.runic_shears)
			return;

		ItemRunicShears item = (ItemRunicShears) ModItems.runic_shears;

		Vec3d hit = event.getHitVec();
		EnumActionResult result = item.onItemUse(player, event.getWorld(), event.getPos(), event.getHand(), event.getFace(), (float) hit.x, (float) hit.y, (float) hit.z);
		if (result == EnumActionResult.SUCCESS) {
			event.setCanceled(true);
		}
	}

	@SubscribeEvent
	public static void onEntityItemPickup(EntityItemPickupEvent event) {
		if (GeneralConfig.AutoRefillPouches) {
			EntityPlayer player = event.getEntityPlayer();
			EntityItem entity = event.getItem();
			if (!entity.world.isRemote) {
				ItemStack stack = entity.getItem().copy();
				Item item = stack.getItem();
				int original = stack.getCount();
				if (HerbRegistry.isHerb(item)) {
					boolean modified = false;
					List<ItemStack> pouches = ServerHerbUtil.getPouches(player);
					for (ItemStack pouch : pouches) {
						PouchHandler handler = PouchHandler.getHandler(pouch);
						int refill = handler.refill(stack);
						if (refill < original) {
							modified = true;
							stack.setCount(refill);
							original = refill;
						}
					}
					if (modified) {
						event.setCanceled(true);
						entity.setDead();
						entity.world.playSound(null, player.getPosition(), SoundEvents.ENTITY_ITEM_PICKUP, SoundCategory.PLAYERS, 0.6f, 0.5f);
						if (!stack.isEmpty()) {
							EntityItem newEntity = new EntityItem(entity.world, entity.posX, entity.posY, entity.posZ, stack);
							newEntity.motionX = entity.motionX;
							newEntity.motionY = entity.motionY;
							newEntity.motionZ = entity.motionZ;
							newEntity.setPickupDelay(0);
							entity.world.spawnEntity(newEntity);
						}
					}
				}
			}
		}
	}

	public static Item MAGMATIC_SOIL = null;

	@SubscribeEvent
	public static void onEntityItemJoinWorld(EntityJoinWorldEvent event) {
		if (MAGMATIC_SOIL == null) {
			MAGMATIC_SOIL = ((BlockBase) ModBlocks.elemental_soil_fire).getItemBlock();
		}
		Entity entity = event.getEntity();
		if (event.getWorld().isRemote) return;

		if (entity instanceof EntityItem && !(entity instanceof EntityItemMagmaticSoil)) {
			EntityItem entityItem = (EntityItem) entity;
			ItemStack stack = entityItem.getItem();
			if (stack.getItem() == MAGMATIC_SOIL) {
				EntityItemMagmaticSoil soil = new EntityItemMagmaticSoil(event.getWorld(), entity.posX, entity.posY, entity.posZ, stack);
				soil.setPickupDelay(40);
				soil.motionX = entity.motionX;
				soil.motionY = entity.motionY;
				soil.motionZ = entity.motionZ;
				entity.setDead();
				event.getWorld().spawnEntity(soil);
			}
		}
	}
}

package epicsquid.roots.handler;

import epicsquid.roots.item.PouchType;
import net.minecraft.item.ItemStack;
import net.minecraftforge.items.IItemHandlerModifiable;

public interface IPouchHandler {

	PouchType getPouchType();

	int refill(ItemStack herbStack);

	default boolean isApothecary() {
		return getPouchType() == PouchType.APOTHECARY;
	}

	default boolean isHerb() {
		return getPouchType() == PouchType.HERB;
	}

	default boolean isCreative() {
		return getPouchType() == PouchType.CREATIVE;
	}

	default boolean isFey() {
		return getPouchType() == PouchType.FEY;
	}

	IItemHandlerModifiable getInventory();

	IItemHandlerModifiable getHerbs();

	void markDirty();
}

package epicsquid.roots.handler;

import epicsquid.roots.init.HerbRegistry;
import epicsquid.roots.item.ItemPouch;
import epicsquid.roots.item.PouchType;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraftforge.common.util.INBTSerializable;
import net.minecraftforge.items.ItemStackHandler;

import javax.annotation.Nonnull;

public class OldPouchHandler implements INBTSerializable<NBTTagCompound> {
	public static final int COMPONENT_POUCH_HERB_SLOTS = 6;
	public static final int COMPONENT_POUCH_INVENTORY_SLOTS = 12;
	public static final int APOTHECARY_POUCH_HERB_SLOTS = 9;
	public static final int APOTHECARY_POUCH_INVENTORY_SLOTS = 18;

	private PouchItemHandler inventorySlots;
	private PouchHerbHandler herbSlots;
	private ItemStack pouch;

	private boolean isApoth = false;

	public OldPouchHandler(ItemStack pouch, int inventorySlots, int herbSlots) {
		this.pouch = pouch;
		if (inventorySlots == APOTHECARY_POUCH_INVENTORY_SLOTS) {
			isApoth = true;
		}
		this.inventorySlots = new PouchItemHandler(inventorySlots);
		this.herbSlots = new PouchHerbHandler(herbSlots);
	}

	public PouchItemHandler getInventory() {
		return inventorySlots;
	}

	public PouchHerbHandler getHerbs() {
		return herbSlots;
	}

	@Override
	public NBTTagCompound serializeNBT() {
		NBTTagCompound tag = new NBTTagCompound();
		tag.setTag("inventory_slots", inventorySlots.serializeNBT());
		tag.setTag("herb_slots", herbSlots.serializeNBT());
		return tag;
	}

	@Override
	public void deserializeNBT(NBTTagCompound nbt) {
		NBTTagCompound inv = nbt.getCompoundTag("inventory_slots");
		NBTTagCompound herb = nbt.getCompoundTag("herb_slots");
		if (isApoth) {
			if (inv.getInteger("Size") != APOTHECARY_POUCH_INVENTORY_SLOTS) {
				inv.setInteger("Size", APOTHECARY_POUCH_INVENTORY_SLOTS);
			}
			if (herb.getInteger("Size") != APOTHECARY_POUCH_HERB_SLOTS) {
				herb.setInteger("Size", APOTHECARY_POUCH_HERB_SLOTS);
			}
		}
		inventorySlots.deserializeNBT(inv);
		herbSlots.deserializeNBT(herb);
	}

	public static OldPouchHandler getHandler(ItemStack stack) {
		OldPouchHandler handler;
		PouchType type = ItemPouch.getPouchType(stack);
		if (type == PouchType.APOTHECARY) {
			handler = new OldPouchHandler(stack, APOTHECARY_POUCH_INVENTORY_SLOTS, APOTHECARY_POUCH_HERB_SLOTS);
		} else {
			handler = new OldPouchHandler(stack, COMPONENT_POUCH_INVENTORY_SLOTS, COMPONENT_POUCH_HERB_SLOTS);
		}
		if (stack.hasTagCompound()) {
			NBTTagCompound tag = stack.getTagCompound();
			if (tag.hasKey("handler")) {
				handler.deserializeNBT(tag.getCompoundTag("handler"));
			}
		}

		return handler;
	}

	public void saveToStack() {
		NBTTagCompound tag = pouch.getTagCompound();
		if (tag == null) {
			tag = new NBTTagCompound();
			pouch.setTagCompound(tag);
		}

		tag.setTag("handler", serializeNBT());
	}

	public class PouchItemHandler extends ItemStackHandler {

		public PouchItemHandler(int size) {
			super(size);
		}

		@Override
		protected void onContentsChanged(int slot) {
			super.onContentsChanged(slot);

			OldPouchHandler.this.saveToStack();
		}

		@Override
		public void setStackInSlot(int slot, @Nonnull ItemStack stack) {
			super.setStackInSlot(slot, stack);

			OldPouchHandler.this.saveToStack();
		}

		@Nonnull
		@Override
		public ItemStack insertItem(int slot, @Nonnull ItemStack stack, boolean simulate) {
			ItemStack result = super.insertItem(slot, stack, simulate);
			OldPouchHandler.this.saveToStack();
			return result;
		}

		@Nonnull
		@Override
		public ItemStack extractItem(int slot, int amount, boolean simulate) {
			ItemStack result = super.extractItem(slot, amount, simulate);

			OldPouchHandler.this.saveToStack();
			return result;
		}
	}

	public class PouchHerbHandler extends PouchItemHandler {
		public PouchHerbHandler(int size) {
			super(size);
		}

		@Override
		public boolean isItemValid(int slot, @Nonnull ItemStack stack) {
			return HerbRegistry.isHerb(stack.getItem());
		}

		public int refill(ItemStack herbStack) {
			if (!containsHerb(herbStack.getItem())) {
				return herbStack.getCount();
			}

			Item herb = herbStack.getItem();
			int count = herbStack.getCount();

			for (ItemStack stack : stacks) {
				if (stack.getItem() == herb) {
					if (stack.getCount() < stack.getMaxStackSize()) {
						int consumed = Math.min(count, stack.getMaxStackSize() - stack.getCount());
						if (consumed > 0) {
							stack.grow(consumed);
							count = Math.max(0, count - consumed);
							OldPouchHandler.this.saveToStack();
						}
					}
				}
				if (count == 0) {
					return 0;
				}
			}

			return count;
		}

		public boolean containsHerb(Item item) {
			for (ItemStack stack : stacks) {
				if (stack.getItem() == item) {
					return true;
				}
			}

			return false;
		}
	}
}

package epicsquid.roots.handler;

import epicsquid.mysticallib.util.ItemUtil;
import epicsquid.roots.Roots;
import epicsquid.roots.item.ItemPouch;
import epicsquid.roots.item.PouchType;
import epicsquid.roots.world.data.PouchHandlerData;
import epicsquid.roots.world.data.PouchHandlerRegistry;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.items.IItemHandlerModifiable;
import net.minecraftforge.items.ItemHandlerHelper;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

public class PouchHandler implements IPouchHandler {

	private IItemHandlerModifiable inventorySlots;
	private IItemHandlerModifiable herbSlots;
	private ItemStack pouch;
	private Runnable markDirty;
	private Function<ItemStack, Integer> filler;

	public PouchHandler(ItemStack pouch) {
		this.pouch = pouch;

		NBTTagCompound tag = ItemUtil.getOrCreateTag(pouch);
		PouchHandlerData data;
		PouchType type = ItemPouch.getPouchType(pouch);
		if (tag.hasUniqueId("bag_id")) {
			data = PouchHandlerRegistry.getData(tag.getUniqueId("bag_id"), type);
		} else {
			data = PouchHandlerRegistry.getNewData(type);
			tag.setUniqueId("bag_id", data.getUuid());
		}
		this.inventorySlots = data.getInventoryHandler();
		this.herbSlots = data.getHerbHandler();
		markDirty = data::markDirty;
		filler = data::refill;

		if (tag.hasKey("handler", Constants.NBT.TAG_COMPOUND)) {
			OldPouchHandler oldPouch = OldPouchHandler.getHandler(pouch);
			List<ItemStack> oldInventory = new ArrayList<>();
			List<ItemStack> oldHerbs = new ArrayList<>();
			OldPouchHandler.PouchItemHandler current = oldPouch.getInventory();
			for (int i = 0; i < current.getSlots(); i++) {
				ItemStack stack = current.getStackInSlot(i);
				if (!stack.isEmpty()) {
					oldInventory.add(stack);
				}
			}
			current = oldPouch.getHerbs();
			for (int i = 0; i < current.getSlots(); i++) {
				ItemStack stack = current.getStackInSlot(i);
				if (!stack.isEmpty()) {
					oldHerbs.add(stack);
				}
			}
			for (ItemStack stack : oldInventory) {
				ItemStack result = ItemHandlerHelper.insertItemStacked(inventorySlots, stack, false);
				if (!result.isEmpty()) {
					Roots.logger.error("Unable to fully merge itemstack " + stack.toString() + " into new component/apothecary inventory.");
				}
			}
			for (ItemStack stack : oldHerbs) {
				ItemStack result = ItemHandlerHelper.insertItemStacked(herbSlots, stack, false);
				if (!result.isEmpty()) {
					Roots.logger.error("Unable to fully merge itemstack " + stack.toString() + " into new component/apothecary herbs.");
				}
			}
			tag.removeTag("handler");
			markDirty();
		}
	}

	@Override
	public int refill(ItemStack herbStack) {
		return this.filler.apply(herbStack);
	}

	@Override
	public PouchType getPouchType() {
		return ItemPouch.getPouchType(pouch);
	}

	@Override
	public IItemHandlerModifiable getInventory() {
		return inventorySlots;
	}

	@Override
	public IItemHandlerModifiable getHerbs() {
		return herbSlots;
	}

	@Override
	public void markDirty() {
		this.markDirty.run();
	}

	@Nullable
	public static PouchHandler getHandler(ItemStack stack) {
		if (!(stack.getItem() instanceof ItemPouch)) {
			return null;
		}
		return new PouchHandler(stack);
	}
}

package epicsquid.roots.init;

import epicsquid.roots.Roots;
