	}

	@Nonnull
	@Override
	public EnumAction getItemUseAction(ItemStack stack) {
		StaffSpellStorage capability = StaffSpellStorage.fromStack(stack);
		if (capability == null) {
			return EnumAction.NONE;
		}
		StaffSpellInfo info = capability.getSelectedInfo();
		if (info != null) {
			SpellBase spell = info.getSpell();
			if (spell != null) {
				if (spell.getCastType() == SpellBase.EnumCastType.CONTINUOUS) {
					return EnumAction.BOW;
				} else {
					return EnumAction.NONE;
				}
			}
		}
		return EnumAction.NONE;
	}

	@SideOnly(Side.CLIENT)
	@Override
	public void initModel() {
		ModelBakery.registerItemVariants(this, new ModelResourceLocation(getRegistryName().toString()), new ModelResourceLocation(getRegistryName().toString() + "_1"));
		ModelLoader.setCustomMeshDefinition(this, stack -> {
			ResourceLocation baseName = getRegistryName();

			StaffSpellStorage capability = StaffSpellStorage.fromStack(stack);
			if (capability != null && capability.hasSpellInSlot()) {
				return new ModelResourceLocation(baseName.toString() + "_1");
			} else {
				return new ModelResourceLocation(baseName.toString());
			}
		});
	}

	public static class StaffColorHandler implements IItemColor {

		@Override
		public int colorMultiplier(@Nonnull ItemStack stack, int tintIndex) {
			StaffSpellStorage capability = StaffSpellStorage.fromStack(stack);
			if (capability != null && capability.hasSpellInSlot() && stack.getItem() instanceof ItemStaff) {
				StaffSpellInfo info = capability.getSelectedInfo();
				if (info == null) {
					return Util.intColor(255, 255, 255);
				}
				SpellBase spell = info.getSpell();
				if (spell != null) {
					if (tintIndex == 1) {
						int r = (int) (255 * spell.getRed1());
						int g = (int) (255 * spell.getGreen1());
						int b = (int) (255 * spell.getBlue1());
						return (r << 16) + (g << 8) + b;
					}
					if (tintIndex == 2) {
						int r = (int) (255 * spell.getRed2());
						int g = (int) (255 * spell.getGreen2());
						int b = (int) (255 * spell.getBlue2());
						return (r << 16) + (g << 8) + b;
					}
				}
				return Util.intColor(255, 255, 255);
			}
			return Util.intColor(255, 255, 255);
		}
	}

	@Override
	public String getHighlightTip(ItemStack stack, String displayName) {
		StaffSpellStorage capability = StaffSpellStorage.fromStack(stack);
		if (capability == null) {
			return displayName;
		}
		String additional = capability.formatSelectedSpell();
		if (additional != null) {
			return displayName + " " + additional;
		}

		return displayName;
	}

	@Override
	public void getSubItems(CreativeTabs tab, NonNullList<ItemStack> subItems) {
		if (tab == this.getCreativeTab()) {
			subItems.add(new ItemStack(this));
			for (SpellBase entry : SpellRegistry.spellRegistry.values()) {
				if (entry.isDisabled()) {
					continue;
				}
				subItems.add(entry.getStaff());
			}
		}
	}
}

package epicsquid.roots.item;

import javax.annotation.Nullable;

public enum PouchType {
	HERB, COMPONENT, APOTHECARY, FEY, CREATIVE;

	public static final int COMPONENT_POUCH_HERB_SLOTS = 6;
	public static final int COMPONENT_POUCH_INVENTORY_SLOTS = 12;
	public static final int APOTHECARY_POUCH_HERB_SLOTS = 9;
	public static final int APOTHECARY_POUCH_INVENTORY_SLOTS = 18;
	public static final int HERB_POUCH_SLOTS = 9;
	public static final int FEY_POUCH_INVENTORY_SLOTS = 6;
	public static final int FEY_POUCH_HERB_SLOTS = 12;

	public int herbSlots() {
		switch (this) {
			case COMPONENT:
				return COMPONENT_POUCH_HERB_SLOTS;
			case APOTHECARY:
				return APOTHECARY_POUCH_HERB_SLOTS;
			case HERB:
				return HERB_POUCH_SLOTS;
			case FEY:
				return FEY_POUCH_HERB_SLOTS;
			default:
				return 0;
		}
	}

	public int inventorySlots() {
		switch (this) {
			case COMPONENT:
				return COMPONENT_POUCH_INVENTORY_SLOTS;
			case APOTHECARY:
				return APOTHECARY_POUCH_INVENTORY_SLOTS;
			case FEY:
				return FEY_POUCH_INVENTORY_SLOTS;
			default:
				return 0;
		}
	}

	@Nullable
	public static PouchType fromOrdinal(int ordinal) {
		int i = 0;
		for (PouchType type : values()) {
			if (i == ordinal) {
				return type;
			}
			i++;
		}
		return null;
	}
}

