	public static class SpellRecipe implements IRootsRecipe<TileEntityMortar> {
		public static SpellRecipe EMPTY = new SpellRecipe();

		private List<Ingredient> ingredients = new ArrayList<>();

		public SpellRecipe(Object... stacks) {
			for (Object stack : stacks) {
				if (stack instanceof Ingredient) {
					ingredients.add((Ingredient) stack);
				} else if (stack instanceof ItemStack) {
					ingredients.add(Ingredient.fromStacks((ItemStack) stack));
				}
			}
		}

		@Override
		public List<Ingredient> getIngredients() {
			return ingredients;
		}
	}
}

package epicsquid.roots.util;

import epicsquid.roots.integration.baubles.pouch.BaublePowderInventoryUtil;
import epicsquid.roots.item.ItemPouch;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraftforge.fml.common.Loader;

import java.util.ArrayList;
import java.util.List;

public class CommonHerbUtil {
	public static ItemStack getFirstPouch(EntityPlayer player) {
		List<ItemStack> pouches = getPouches(player);
		if (pouches.isEmpty()) {
			return ItemStack.EMPTY;
		}

		return pouches.get(0);
	}

	public static List<ItemStack> getPouches(EntityPlayer player) {
		List<ItemStack> result = new ArrayList<>();
		if (Loader.isModLoaded("baubles")) {
			ItemStack stack = BaublePowderInventoryUtil.getPouch(player);
			if (!stack.isEmpty()) {
				result.add(stack);
			}
		}

		for (int i = 0; i < 36; i++) {
			if (player.inventory.getStackInSlot(i).getItem() instanceof ItemPouch) {
				ItemStack pouch = player.inventory.getStackInSlot(i);
				result.add(pouch);
			}
		}

		return result;
	}
}

package epicsquid.roots.util;

import epicsquid.mysticallib.network.PacketHandler;
import epicsquid.roots.api.Herb;
import epicsquid.roots.init.ModItems;
import epicsquid.roots.item.ItemPouch;
import epicsquid.roots.item.ItemSylvanArmor;
import epicsquid.roots.network.MessageUpdateHerb;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.item.ItemStack;

import java.util.Collections;
import java.util.List;

public class ServerHerbUtil {
	public static ItemStack getFirstPouch(EntityPlayer player) {
		if (player.world.isRemote) {
			return ItemStack.EMPTY;
		}

		return CommonHerbUtil.getFirstPouch(player);
	}

	public static List<ItemStack> getPouches(EntityPlayer player) {
		if (player.world.isRemote) {
			return Collections.emptyList();
		}

		return CommonHerbUtil.getPouches(player);
	}

	public static double getHerbAmount(EntityPlayer player, Herb herb) {
		if (player.world.isRemote) {
			return 0;
		}

		List<ItemStack> pouches = getPouches(player);
		if (pouches.isEmpty()) return -1.0;

		double quantity = 0;
		for (ItemStack pouch : pouches) {
			// Hard-coding for creative pouch
			if (pouch.getItem() == ModItems.creative_pouch) {
				quantity += 999;
			} else {
				quantity += ItemPouch.getHerbQuantity(player, pouch, herb);
			}
		}

		return quantity;
	}

	public static void removePowder(EntityPlayer player, Herb herb, double amount) {
		if (player.world.isRemote) {
			return;
		}

		List<ItemStack> pouches = getPouches(player);

		double quantity = 0;

		// TODO: Cost reduction is calculated here
		double total = amount - amount * ItemSylvanArmor.sylvanBonus(player);
		for (ItemStack pouch : pouches) {
			if (pouch.getItem() == ModItems.creative_pouch) {
				continue;
			}

			if (total > 0) {
				total = ItemPouch.useQuantity(player, pouch, herb, total);
			}

			quantity += ItemPouch.getHerbQuantity(player, pouch, herb);
		}

		MessageUpdateHerb message = new MessageUpdateHerb(herb, quantity);
		PacketHandler.INSTANCE.sendTo(message, (EntityPlayerMP) player);
	}
}

package epicsquid.roots.world.data;

import epicsquid.roots.init.HerbRegistry;
import epicsquid.roots.item.PouchType;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.world.storage.WorldSavedData;
import net.minecraftforge.items.ItemStackHandler;

import javax.annotation.Nonnull;
import java.util.List;
import java.util.UUID;

@SuppressWarnings({"WeakerAccess", "NullableProblems"})
public class PouchHandlerData extends WorldSavedData {
	private static final String identifier = "Inventory-";

	private UUID uuid;
	private MarkDirtyHandler inventoryHandler;
	private HerbHandler herbHandler;
	private PouchType type = null;
	private boolean defer = false;

	public static String name(UUID uuid) {
		return identifier + uuid.toString();
	}

	public PouchType getType() {
		return type;
	}

	public PouchHandlerData(String identifier) {
		super(identifier);
		this.uuid = UUID.fromString(identifier.replace(PouchHandlerData.identifier, ""));
		defer = true;
	}

	public PouchHandlerData(UUID uuid, PouchType type) {
		super(name(uuid));
		this.uuid = uuid;
		this.type = type;
		createHandler();
	}

	public void upgrade(PouchType newType) {
		if (type.ordinal() >= newType.ordinal()) {
			return;
		}

		this.type = newType;
		this.inventoryHandler.setSize(type.inventorySlots());
		this.herbHandler.setSize(type.herbSlots());
		markDirty();
	}

	private void createHandler() {
		if (type == null) {
			throw new IllegalStateException("Attempted to instantiate PouchHandlerData before type was set.");
		}
		this.inventoryHandler = new MarkDirtyHandler(type.inventorySlots());
		this.herbHandler = new HerbHandler(type.herbSlots());
	}

	public int refill(ItemStack herbStack) {
		return herbHandler.refill(herbStack);
	}

	public UUID getUuid() {
		return uuid;
	}

	public MarkDirtyHandler getInventoryHandler() {
		return inventoryHandler;
	}

	public HerbHandler getHerbHandler() {
		return herbHandler;
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		this.type = PouchType.fromOrdinal(nbt.getInteger("pouch"));
		if (defer) {
			createHandler();
		}
		inventoryHandler.deserializeNBT(nbt.getCompoundTag("inventory"));
		herbHandler.deserializeNBT(nbt.getCompoundTag("herbs"));
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound compound) {
		compound.setInteger("pouch", type.ordinal());
		compound.setTag("inventory", inventoryHandler.serializeNBT());
		compound.setTag("herbs", herbHandler.serializeNBT());
		return compound;
	}

	public class MarkDirtyHandler extends ItemStackHandler {
		public MarkDirtyHandler(int size) {
			super(size);
		}

		@Override
		protected void onContentsChanged(int slot) {
			super.onContentsChanged(slot);
			markDirty();
		}

		@Override
		public void setSize(int size) {
			List<ItemStack> original = stacks;
			super.setSize(size);
			for (int i = 0; i < Math.min(original.size(), size); i++) {
				stacks.set(i, original.get(i));
			}
		}
	}

	public class HerbHandler extends MarkDirtyHandler {
		public HerbHandler(int size) {
			super(size);
		}

		@Override
		public boolean isItemValid(int slot, @Nonnull ItemStack stack) {
			return HerbRegistry.isHerb(stack.getItem());
		}

		public int refill(ItemStack herbStack) {
			if (!containsHerb(herbStack.getItem())) {
				return herbStack.getCount();
			}

			Item herb = herbStack.getItem();
			int count = herbStack.getCount();

			for (int i = 0; i < stacks.size(); i++) {
				ItemStack stack = stacks.get(i);
				if (stack.getItem() == herb) {
					if (stack.getCount() < stack.getMaxStackSize()) {
						int consumed = Math.min(count, stack.getMaxStackSize() - stack.getCount());
						if (consumed > 0) {
							stack.grow(consumed);
							count = Math.max(0, count - consumed);
							stacks.set(i, stack);
						}
					}
				}
				if (count == 0) {
					return 0;
				}
			}

			return count;
		}

		public boolean containsHerb(Item item) {
			for (ItemStack stack : stacks) {
				if (stack.getItem() == item) {
					return true;
				}
			}

			return false;
		}
	}
}

package epicsquid.roots.world.data;

import epicsquid.roots.item.PouchType;
import net.minecraft.world.WorldServer;
import net.minecraftforge.fml.common.FMLCommonHandler;

import java.util.UUID;

@SuppressWarnings("WeakerAccess")
public class PouchHandlerRegistry {
	public static PouchHandlerData getNewData(PouchType type) {
		return getData(UUID.randomUUID(), type);
	}

	@SuppressWarnings("ConstantConditions")
	public static PouchHandlerData getData(UUID id, PouchType type) {
		WorldServer server = FMLCommonHandler.instance().getMinecraftServerInstance().getWorld(0);
		PouchHandlerData data = (PouchHandlerData) server.getMapStorage().getOrLoadData(PouchHandlerData.class, PouchHandlerData.name(id));

		// I feel this check could be problematic
		if (data == null || data.getType() != type) {
			data = new PouchHandlerData(id, type);
			server.getMapStorage().setData(PouchHandlerData.name(id), data);
		}

		return data;
	}
}
